mapper.update:
update user

    set uname = #{uname}


    ,UPHONE=#{uphone}


    ,UIDENTITY=#{uidentity}


    ,UAVATAR=#{uavatar}


    ,UDescription=#{uDescription}

where UID = #{uid}

mapper.select:
select sys_user_login.UserName, sys_user_login.RID, sys_user_login.UserState, sys_user_login.UID, user.UNAME, user.UPHONE, user.UIDENTITY, user.UAVATAR, user.UDescription, role.Description from sys_user_login, user, role where sys_user_login.UID = user.UID and sys_user_login.RID = role.RID
and sys_user_login.UserName = #{username}
and user.UNAME = #{UName}
and sys_user_login.RID = #{rid}
and sys_user_login.UserState = #{state}
order by sys_user_login.UID
